        T_authority = url_components['authority']
        T_path = remove_dot_segments(url_components['path'])
        T_query = url_components['query']
    else:
        if url_components['authority']:
            T_authority = url_components['authority']
            T_path = remove_dot_segments(url_components['path'])
            T_query = url_components['query']
        else:
            if url_components['path'] == '':
                T_path = base_components['path']
                if url_components['query']:
                    T_query = url_components['query']
                else:
                    T_query = base_components['query']
            else:
                if url_components['path'].startswith('/'):
                    T_path = remove_dot_segments(url_components['path'])
                else:
                    # Merge B.path and R.path
                    if base_components['authority'] and not base_components['path']:
                        T_path = '/' + url_components['path']
                    else:
                        # Remove last segment from B.path
                        last_slash = base_components['path'].rfind('/')
                        if last_slash != -1:
                            T_path = base_components['path'][:last_slash + 1] + url_components['path']
                        else:
                            T_path = url_components['path']
                    T_path = remove_dot_segments(T_path)
                T_query = url_components['query']
        T_scheme = base_components['scheme']
        if not url_components['authority']:
            T_authority = base_components['authority']

    return build_url(T_scheme, T_authority, T_path, T_query, T_fragment)
